<script setup lang="ts">
export type ErrorCriteria = {httpPercent: number; workflowPercent: number; businessEnabled: boolean; businessPercent: number}
const props=defineProps<{modelValue:ErrorCriteria}>()
const emit=defineEmits<{'update:modelValue':[ErrorCriteria]}>()
function value(key:keyof ErrorCriteria,event:Event){const input=event.target as HTMLInputElement;emit('update:modelValue',{...props.modelValue,[key]:key==='businessEnabled'?input.checked:Number(input.value)})}
</script>
<template><section class="load-error-criteria"><h3>错误率验收标准</h3><p>以下为新建默认值，请按业务要求调整。HTTP 成功不等于业务成功；若选择业务断言标准但未执行断言，报告会提示证据不足。</p><div><label>HTTP 错误率不超过（%）<input data-testid="threshold-http" type="number" min="0" max="100" step="0.1" :value="modelValue.httpPercent" @input="value('httpPercent',$event)" /></label><label>完整链路失败率不超过（%）<input data-testid="threshold-workflow" type="number" min="0" max="100" step="0.1" :value="modelValue.workflowPercent" @input="value('workflowPercent',$event)" /></label></div><label class="error-criteria-check"><input data-testid="threshold-business-enabled" type="checkbox" :checked="modelValue.businessEnabled" @change="value('businessEnabled',$event)" /><span>同时要求业务断言达标</span></label><label v-if="modelValue.businessEnabled">业务断言失败率不超过（%）<input data-testid="threshold-business" type="number" min="0" max="100" step="0.1" :value="modelValue.businessPercent" @input="value('businessPercent',$event)" /></label><small>这里决定最终是否达标；“HTTP 错误保护停止”单独控制执行过程中是否提前中止。</small></section></template>
<style scoped>.load-error-criteria{display:grid;gap:12px;padding:16px;border:1px solid #dce5ee;border-radius:8px}.load-error-criteria h3,.load-error-criteria p{margin:0}.load-error-criteria p,.load-error-criteria small{font-size:13px;color:#617086;line-height:1.6}.load-error-criteria>div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.load-error-criteria label{display:grid;gap:6px;font-size:13px;min-width:0}.load-error-criteria input[type=number]{min-height:36px;padding:8px;min-width:0;box-sizing:border-box}.load-error-criteria .error-criteria-check{display:flex;align-items:center;gap:8px}.error-criteria-check input{width:18px;height:18px;flex:0 0 18px;margin:0}@media(max-width:700px){.load-error-criteria>div{grid-template-columns:1fr}}</style>
